-- ════════════════════════════════════════════════════════
-- 254 — Huitième recensement : les ajouts aux fiches existantes,
--       lots 08 et 09 (six lignes de gamme, un paragraphe) — fin des
--       ajouts
-- ────────────────────────────────────────────────────────
-- D'OÙ ILS VIENNENT. Comme les 250 et 251 : des marques que l'atlas
-- n'avait pas et qui n'auront pas de fiche, parce qu'elles appartiennent à
-- une maison qui en a déjà une. Cette migration clôt les ajouts du
-- huitième recensement.
--
-- ── CE QUI ENTRE ────────────────────────────────────────
--   Lignes de gamme   Dominico, Casa de Nicaragua, La Libertad, La
--                     Capitana, Corrida et Nicaroma (Villiger), toutes
--                     sur la page des cigares roulés à la main de la
--                     maison en octobre 2026
--   Mention           Edition One (Warped) : la société de Kyle et
--                     Devin Gellis, dont le seul cigare, Cloud Hopper,
--                     est présenté par Warped parmi ses lignes
--
-- ── CE QUI RESTE OÙ IL EST ──────────────────────────────
-- Manuel Alonso est déjà dans la gamme de Tabacosta, sous « Manuel Alonso
-- Gran Selección », depuis la 244.
--
-- ── À CORRIGER DANS LES FICHES HÔTES ────────────────────
-- Villiger (la fiche dit des « manufactures partenaires à Estelí », alors
-- que Villiger de Nicaragua est son usine propre, et que Cuellar Nicaragua
-- est dite produite par Tabacalera Palma) ; Warped (la fiche date Cloud
-- Hopper de 2017 et ne cite pas Edition One, alors que le paragraphe écrit
-- un lancement discret en 2016 et le grand public à l'été 2017) ;
-- Tabacosta (la dernière phrase de l'histoire, « Cigarworld.de vend encore
-- des Manuel Alonso », ne repose que sur des reliquats, et Gran Selección
-- n'a pas de trace datée depuis 2016).
--
-- ── DIVERGENCES ÉCRITES ─────────────────────────────────
-- Corrida, roulée à Danlí chez Plasencia ou chez ABAM selon deux comptes
-- rendus ; La Libertad, roulée au Honduras, puis en République
-- dominicaine, puis à Estelí ; Edition One, nom que la page de Warped
-- n'emploie pas.
--
-- Rejouable : chaque ajout est gardé par un LOCATE (le paragraphe, le
-- fragment de source) ou par le nom de la ligne ; la gamme est relue en
-- base et réécrite en littéral dans chaque langue ; sceaux `machine`.
-- ════════════════════════════════════════════════════════

-- ── Villiger — gamme : Dominico, Casa de Nicaragua, La Libertad, La Capitana, Corrida, Nicaroma ──
UPDATE `brands` SET
  `gamme` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"La gamme d''exception — hommage au Tessin, la Suisse italophone. Cape oscuro d''Équateur sur assemblage nicaraguayen et brésilien. Profil plus intense, chocolat noir et poivre long. La réponse suisse à la question de ce que l''Europe peut opposer aux grandes maisons du Nouveau Monde."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Collaboration avec la famille Cuellar, à Estelí. Cape Colorado naturelle sur assemblage nicaraguayen pur. Le positionnement suisse dans le Nouveau Monde — précis, régulier, moins aventureux que Padrón mais très fiable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nom de vieille marque cubaine, relancé par Villiger en 2007 comme cigare dominicain, roulé à l''ABAM — la fabrique de Villiger en République dominicaine, que cette fiche nomme ici. Le recensement de cet atlas le prenait pour une maison.","vitolas":[],"wrapper":"Non divulguée"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Équateur)","vitolas":[],"story":"Ligne de République dominicaine que la page de la maison, en octobre 2026, dit légère à moyenne et abordable, de niveau 2 sur 5 sur l''échelle de Villiger, en cinq formats : Perla, Corona, Robusto, Torpedo et Churchill. Cigarworld.de, détaillant allemand, la dit roulée à la main en longfiller à ABAM Cigars, en bundles, sous une cape Connecticut Shade d''Équateur, avec un liant d''Indonésie et une tripe Piloto de République dominicaine et du Nicaragua ; la marque date du début des années 2000 selon ce détaillant, qui la tient à son catalogue, pour la Corona, depuis le 7 décembre 2010."},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Équateur (H-2000)","vitolas":[],"story":"Présentée en 2014 par Villiger selon Cigarworld.de, qui la tient à son catalogue depuis le 12 août 2014 et la dit roulée à la main en mediumfiller, sous une cape H-2000 d''Équateur, avec un liant d''Indonésie et une tripe du Nicaragua. Villiger la compte parmi les marques de son usine d''Estelí, achevée fin septembre 2021 ; en octobre 2026, la page de la maison donne cinq formats d''origine Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de niveau 4 sur 5 sur son échelle."},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo (Nicaragua)","vitolas":[],"story":"Apparue au début des années 2000 chez Liberty Cigar Company, en Allemagne, puis entrée dans le groupe Villiger, elle a quitté le Honduras, où Plasencia la roulait, puis la République dominicaine, où ABAM la roulait, pour Estelí : un nouveau mélange, cape criollo du Nicaragua, liant du Cibao dominicain, tripe nicaraguayenne de Jalapa et d''Estelí, est montré en janvier 2022 au salon TPE de Las Vegas, en Corona, Robusto et Gran Toro. En octobre 2026, la page de la maison la range parmi ses cigares faits à la main, en quatre formats (Gordito, Robusto, Corona, Gran Toro) de niveau 4 sur 5 sur son échelle."},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Équateur)","vitolas":[],"story":"Relancée en 2025 avec un nouveau mélange, cape Connecticut Shade d''Équateur, liant du Nicaragua, tripe du Nicaragua et de République dominicaine, annoncée au salon PCA en avril 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) et Churchill (7 x 50) ; la version précédente avait une cape habano, dit un compte rendu de juillet 2026. Cigarworld.de la dit roulée à la main en longfiller à Estelí par Tabacalera Villiger de Nicaragua, dans les locaux de Joya de Nicaragua, et la tient à son catalogue depuis le 28 août 2025 ; en octobre 2026, la page de la maison donne Robusto, Toro et Churchill, de niveau 2 sur 5 sur son échelle."},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"Non divulguée","vitolas":[],"story":"Lancée en Europe en mai 2017 en deux versions, Honduras (roulée à Danlí par Nestor A. Plasencia, dit un compte rendu de lancement) et République dominicaine (faite à ABAM, dit un autre compte rendu), en Robusto+ (5 x 56) et Toro+ (6 x 52). En octobre 2026, la page de la maison la présente en quatre origines, Honduras, République dominicaine, Nicaragua et Brésil, de niveau 4, 2,5, 5 et 3,5 sur 5 sur son échelle, et la destine aux amateurs de cigares roulés à la main ; Villiger compte Corrida parmi les marques de son usine d''Estelí, achevée fin septembre 2021."},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Série présentée à InterTabac 2023, à Dortmund, selon Cigarworld.de, qui la dit roulée à la main en longfiller à Estelí en partenariat avec Joya de Nicaragua, cape et tripe du Nicaragua sur un liant d''Indonésie, et la tient à son catalogue depuis le 25 septembre 2023 pour le 5 x 52. En octobre 2026, la page de la maison donne trois formats nommés par leurs dimensions, 4 x 56, 5 x 52 et 6 x 54, de niveau 4 sur 5 sur son échelle ; un aperçu d''avril 2013 présentait déjà sous ce nom une ligne à trois capes."}]',
  `gamme_en` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"The exceptional range — tribute to the Italian-speaking Swiss region (Ticino). Ecuadorian Oscuro wrapper on Nicaragua/Brazil blend. More intense profile, dark chocolate and long pepper. Switzerland''s answer to what the continent can offer against the great New World cigars."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Collaboration with the Cuellar family in Estelí. Natural Colorado wrapper on a pure Nicaraguan blend. The Swiss positioning in the New World — precise, consistent, less adventurous than Padrón but highly reliable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"An old Cuban brand name, relaunched by Villiger in 2007 as a Dominican cigar, rolled at ABAM — Villiger''s factory in the Dominican Republic, which this entry names here. This atlas''s census took it for a house.","vitolas":[],"wrapper":"Undisclosed"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"A line from the Dominican Republic that the company''s page, in October 2026, calls light to medium and affordable, at level 2 of 5 on Villiger''s scale, in five sizes: Perla, Corona, Robusto, Torpedo and Churchill. Cigarworld.de, a German retailer, says it is hand-rolled longfiller at ABAM Cigars, in bundles, under a Connecticut Shade wrapper from Ecuador, with a binder from Indonesia and a Piloto filler from the Dominican Republic and Nicaragua; the brand dates from the early 2000s according to that retailer, which has carried it in its catalogue, for the Corona, since 7 December 2010."},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuador (H-2000)","vitolas":[],"story":"Presented in 2014 by Villiger, according to Cigarworld.de, which has carried it in its catalogue since 12 August 2014 and says it is hand-rolled mediumfiller, under an H-2000 wrapper from Ecuador, with a binder from Indonesia and a filler from Nicaragua. Villiger counts it among the brands of its factory in Estelí, completed at the end of September 2021; in October 2026, the company''s page gives five sizes of Nicaraguan origin (Perla, Corona, Robusto, Torpedo, Churchill), at level 4 of 5 on its scale."},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo (Nicaragua)","vitolas":[],"story":"It appeared in the early 2000s at Liberty Cigar Company, in Germany, then joined the Villiger group, and it left Honduras, where Plasencia rolled it, then the Dominican Republic, where ABAM rolled it, for Estelí: a new blend, with a criollo wrapper from Nicaragua, a binder from the Dominican Cibao and a Nicaraguan filler from Jalapa and Estelí, was shown in January 2022 at the TPE show in Las Vegas, in Corona, Robusto and Gran Toro. In October 2026, the company''s page places it among its handmade cigars, in four sizes (Gordito, Robusto, Corona, Gran Toro), at level 4 of 5 on its scale."},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Relaunched in 2025 with a new blend, a Connecticut Shade wrapper from Ecuador, a binder from Nicaragua and a filler from Nicaragua and the Dominican Republic, it was announced at the PCA show in April 2025 in Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) and Churchill (7 x 50); the previous version had a habano wrapper, says a report from July 2026. Cigarworld.de says it is hand-rolled longfiller in Estelí by Tabacalera Villiger de Nicaragua, on the premises of Joya de Nicaragua, and has carried it in its catalogue since 28 August 2025; in October 2026, the company''s page gives Robusto, Toro and Churchill, at level 2 of 5 on its scale."},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"Undisclosed","vitolas":[],"story":"Launched in Europe in May 2017 in two versions, Honduras (rolled in Danlí by Nestor A. Plasencia, says a launch report) and Dominican Republic (made at ABAM, says another report), in Robusto+ (5 x 56) and Toro+ (6 x 52). In October 2026, the company''s page presents it in four origins, Honduras, the Dominican Republic, Nicaragua and Brazil, at levels 4, 2.5, 5 and 3.5 of 5 on its scale, and aims it at enthusiasts of hand-rolled cigars; Villiger counts Corrida among the brands of its factory in Estelí, completed at the end of September 2021."},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"A series presented at InterTabac 2023, in Dortmund, according to Cigarworld.de, which says it is hand-rolled longfiller in Estelí in partnership with Joya de Nicaragua, with wrapper and filler from Nicaragua and a binder from Indonesia, and has carried it in its catalogue since 25 September 2023 for the 5 x 52. In October 2026, the company''s page gives three sizes named by their dimensions, 4 x 56, 5 x 52 and 6 x 54, at level 4 of 5 on its scale; a preview from April 2013 already presented a three-wrapper line under this name."}]',
  `gamme_es` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"La gama de excepción, homenaje a la región italófona de Suiza (el Tesino). Capa Oscuro ecuatoriana sobre ligada de Nicaragua y Brasil. Perfil más intenso, chocolate negro y pimienta larga. La respuesta suiza a la pregunta de qué puede ofrecer el continente frente a los grandes del New World."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Colaboración con la familia Cuellar en Estelí. Capa Colorado natural sobre ligada nicaragüense pura. El posicionamiento suizo en el New World: preciso, regular, menos aventurero que Padrón pero muy fiable."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Un nombre de vieja marca cubana, relanzado por Villiger en 2007 como puro dominicano, liado en ABAM — la fábrica de Villiger en la República Dominicana, que esta ficha nombra aquí. El censo de este atlas lo tomaba por una casa.","vitolas":[],"wrapper":"No divulgada"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Línea de la República Dominicana que la página de la casa, en octubre de 2026, califica de ligera a media y asequible, de nivel 2 sobre 5 en la escala de Villiger, en cinco formatos: Perla, Corona, Robusto, Torpedo y Churchill. Cigarworld.de, minorista alemán, indica que está enrollada a mano en longfiller en ABAM Cigars, en bundles, con capa Connecticut Shade de Ecuador, capote de Indonesia y tripa Piloto de la República Dominicana y de Nicaragua; la marca data de principios de los años 2000 según ese minorista, que la tiene en su catálogo, para la Corona, desde el 7 de diciembre de 2010."},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuador (H-2000)","vitolas":[],"story":"Presentada en 2014 por Villiger según Cigarworld.de, que la tiene en su catálogo desde el 12 de agosto de 2014 e indica que está enrollada a mano en mediumfiller, con capa H-2000 de Ecuador, capote de Indonesia y tripa de Nicaragua. Villiger la cuenta entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021; en octubre de 2026, la página de la casa ofrece cinco formatos de origen Nicaragua (Perla, Corona, Robusto, Torpedo, Churchill), de nivel 4 sobre 5 en su escala."},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo (Nicaragua)","vitolas":[],"story":"Surgida a principios de los años 2000 en Liberty Cigar Company, en Alemania, y después integrada en el grupo Villiger, dejó Honduras, donde la enrollaba Plasencia, y luego la República Dominicana, donde la enrollaba ABAM, para pasar a Estelí: una nueva mezcla, con capa criollo de Nicaragua, capote del Cibao dominicano y tripa nicaragüense de Jalapa y de Estelí, se mostró en enero de 2022 en el salón TPE de Las Vegas, en Corona, Robusto y Gran Toro. En octubre de 2026, la página de la casa la sitúa entre sus puros hechos a mano, en cuatro formatos (Gordito, Robusto, Corona, Gran Toro), de nivel 4 sobre 5 en su escala."},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"Relanzada en 2025 con una nueva mezcla, capa Connecticut Shade de Ecuador, capote de Nicaragua, tripa de Nicaragua y de la República Dominicana, anunciada en el salón PCA en abril de 2025 en Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) y Churchill (7 x 50); la versión anterior tenía una capa habano, dice una crónica de julio de 2026. Cigarworld.de indica que está enrollada a mano en longfiller en Estelí por Tabacalera Villiger de Nicaragua, en las instalaciones de Joya de Nicaragua, y la tiene en su catálogo desde el 28 de agosto de 2025; en octubre de 2026, la página de la casa ofrece Robusto, Toro y Churchill, de nivel 2 sobre 5 en su escala."},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"No divulgada","vitolas":[],"story":"Lanzada en Europa en mayo de 2017 en dos versiones, Honduras (enrollada en Danlí por Nestor A. Plasencia, dice una crónica del lanzamiento) y República Dominicana (hecha en ABAM, dice otra crónica), en Robusto+ (5 x 56) y Toro+ (6 x 52). En octubre de 2026, la página de la casa la presenta en cuatro orígenes, Honduras, República Dominicana, Nicaragua y Brasil, de nivel 4, 2,5, 5 y 3,5 sobre 5 en su escala, y la destina a los aficionados a los puros enrollados a mano; Villiger cuenta Corrida entre las marcas de su fábrica de Estelí, terminada a finales de septiembre de 2021."},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Serie presentada en InterTabac 2023, en Dortmund, según Cigarworld.de, que indica que está enrollada a mano en longfiller en Estelí en colaboración con Joya de Nicaragua, con capa y tripa de Nicaragua sobre un capote de Indonesia, y la tiene en su catálogo desde el 25 de septiembre de 2023 para el 5 x 52. En octubre de 2026, la página de la casa ofrece tres formatos designados por sus dimensiones, 4 x 56, 5 x 52 y 6 x 54, de nivel 4 sobre 5 en su escala; un avance de abril de 2013 presentaba ya con ese nombre una línea de tres capas."}]',
  `gamme_de` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"Die Ausnahmelinie — eine Hommage an die italienischsprachige Schweiz (Tessin). Ecuadorianisches Oscuro-Deckblatt auf einer Mischung aus Nicaragua und Brasilien. Intensiveres Profil, Zartbitterschokolade und Langpfeffer. Die Schweizer Antwort auf die Frage, was der Kontinent den großen New-World-Zigarren entgegenzusetzen hat."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"Zusammenarbeit mit der Familie Cuellar in Estelí. Natürliches Colorado-Deckblatt auf reiner nicaraguanischer Mischung. Die schweizerische Position in der New World — genau, gleichmäßig, weniger wagemutig als Padrón, dafür sehr verlässlich."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"Ein alter kubanischer Markenname, 2007 von Villiger als dominikanische Zigarre neu lanciert, gerollt bei ABAM — der Fabrik von Villiger in der Dominikanischen Republik, die dieser Eintrag hier nennt. Die Zählung dieses Atlas hielt ihn für ein Haus.","vitolas":[],"wrapper":"Nicht angegeben"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (Ecuador)","vitolas":[],"story":"Eine Linie aus der Dominikanischen Republik; die Seite des Hauses nennt sie im Oktober 2026 leicht bis mittelkräftig und erschwinglich, auf Stufe 2 von 5 der Villiger-Skala, in fünf Formaten: Perla, Corona, Robusto, Torpedo und Churchill. Cigarworld.de, ein deutscher Händler, gibt an, sie sei bei ABAM Cigars als Longfiller von Hand gerollt, in Bundles, mit einem Deckblatt Connecticut Shade aus Ecuador, einem Umblatt aus Indonesien und einer Einlage Piloto aus der Dominikanischen Republik und aus Nicaragua; die Marke stammt laut diesem Händler aus dem Anfang der 2000er-Jahre, und er führt sie, für die Corona, seit dem 7. Dezember 2010 in seinem Katalog."},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"Ecuador (H-2000)","vitolas":[],"story":"Laut Cigarworld.de wurde sie 2014 von Villiger vorgestellt; der Händler führt sie seit dem 12. August 2014 in seinem Katalog und gibt an, sie sei als Mediumfiller von Hand gerollt, mit einem Deckblatt H-2000 aus Ecuador, einem Umblatt aus Indonesien und einer Einlage aus Nicaragua. Villiger zählt sie zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde; im Oktober 2026 nennt die Seite des Hauses fünf Formate nicaraguanischer Herkunft (Perla, Corona, Robusto, Torpedo, Churchill), auf Stufe 4 von 5 der Skala des Hauses."},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo (Nicaragua)","vitolas":[],"story":"Anfang der 2000er-Jahre bei der Liberty Cigar Company in Deutschland entstanden und dann zur Villiger-Gruppe gekommen, hat sie Honduras verlassen, wo Plasencia sie rollte, danach die Dominikanische Republik, wo ABAM sie rollte, und ist nach Estelí gezogen: Eine neue Mischung, mit einem Deckblatt criollo aus Nicaragua, einem Umblatt aus dem dominikanischen Cibao und einer nicaraguanischen Einlage aus Jalapa und Estelí, wurde im Januar 2022 auf der Messe TPE in Las Vegas gezeigt, als Corona, Robusto und Gran Toro. Im Oktober 2026 führt die Seite des Hauses sie unter ihren handgefertigten Zigarren auf, in vier Formaten (Gordito, Robusto, Corona, Gran Toro), auf Stufe 4 von 5 der Skala des Hauses."},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (Ecuador)","vitolas":[],"story":"2025 mit einer neuen Mischung neu aufgelegt, Deckblatt Connecticut Shade aus Ecuador, Umblatt aus Nicaragua, Einlage aus Nicaragua und der Dominikanischen Republik, auf der Messe PCA im April 2025 angekündigt als Lonsdale (6 x 43), Robusto (5 x 50), Toro (6 x 50) und Churchill (7 x 50); die vorherige Version hatte ein Deckblatt habano, sagt ein Bericht vom Juli 2026. Cigarworld.de gibt an, sie sei in Estelí von Tabacalera Villiger de Nicaragua als Longfiller von Hand gerollt worden, in den Räumen von Joya de Nicaragua, und führt sie seit dem 28. August 2025 in seinem Katalog; im Oktober 2026 nennt die Seite des Hauses Robusto, Toro und Churchill, auf Stufe 2 von 5 der Skala des Hauses."},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"Nicht angegeben","vitolas":[],"story":"Im Mai 2017 in Europa in zwei Versionen eingeführt, Honduras (in Danlí von Nestor A. Plasencia gerollt, sagt ein Bericht zur Markteinführung) und Dominikanische Republik (bei ABAM gefertigt, sagt ein anderer Bericht), als Robusto+ (5 x 56) und Toro+ (6 x 52). Im Oktober 2026 stellt die Seite des Hauses sie in vier Herkünften vor, Honduras, Dominikanische Republik, Nicaragua und Brasilien, auf den Stufen 4, 2,5, 5 und 3,5 von 5 der Skala des Hauses, und richtet sie an Liebhaber von handgerollten Zigarren; Villiger zählt Corrida zu den Marken seiner Fabrik in Estelí, die Ende September 2021 fertiggestellt wurde."},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"Nicaragua","vitolas":[],"story":"Eine Serie, laut Cigarworld.de auf der InterTabac 2023 in Dortmund vorgestellt; der Händler gibt an, sie sei in Estelí in Partnerschaft mit Joya de Nicaragua als Longfiller von Hand gerollt, mit Deckblatt und Einlage aus Nicaragua und einem Umblatt aus Indonesien, und führt sie seit dem 25. September 2023 für das 5 x 52 in seinem Katalog. Im Oktober 2026 nennt die Seite des Hauses drei nach ihren Maßen benannte Formate, 4 x 56, 5 x 52 und 6 x 54, auf Stufe 4 von 5 der Skala des Hauses; eine Vorschau vom April 2013 stellte unter diesem Namen bereits eine Linie mit drei Deckblättern vor."}]',
  `gamme_zh` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"非凡系列——向瑞士的意大利语区（提契诺）致敬。厄瓜多尔 Oscuro 茄衣，配尼加拉瓜与巴西茄芯。风格更浓烈，带黑巧克力与荜拨。面对新世界的大牌，欧洲大陆能拿出什么？这是瑞士给出的答案。"},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"与 Estelí 的 Cuellar 家族合作之作。天然 Colorado 茄衣，配纯尼加拉瓜茄芯。这是瑞士人在新世界的站位——精准、稳定，不如 Padrón 冒险，却非常可靠。"},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"一个古巴老牌名，2007年由 Villiger 以多米尼加雪茄的身份重启，在 ABAM——Villiger 在多米尼加共和国的工厂——卷制，本词条在此点名。本图集的普查曾把它当作一家公司。","vitolas":[],"wrapper":"未公开"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade（厄瓜多尔）","vitolas":[],"story":"来自多米尼加共和国的系列，公司页面在2026年十月称其强度为轻至中等、价格实惠，在Villiger的等级表上为2级（共5级），共有五种规格：Perla、Corona、Robusto、Torpedo和Churchill。德国零售商Cigarworld.de称其在ABAM Cigars手工卷制，采用longfiller，以bundles形式销售，茄衣为厄瓜多尔Connecticut Shade，茄套来自印尼，茄芯为多米尼加共和国与尼加拉瓜的Piloto；据该零售商称，该品牌可追溯至2000年代初，该零售商自2010年十二月七日起将Corona收入目录。"},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"厄瓜多尔（H-2000）","vitolas":[],"story":"据Cigarworld.de称，该系列由Villiger于2014年发布；该零售商自2014年八月十二日起将其收入目录，称其手工卷制，采用mediumfiller，茄衣为厄瓜多尔H-2000，茄套来自印尼，茄芯来自尼加拉瓜。Villiger将其列入位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工；2026年十月，公司页面列出五种产地为尼加拉瓜的规格（Perla、Corona、Robusto、Torpedo、Churchill），在其等级表上为4级（共5级）。"},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo（尼加拉瓜）","vitolas":[],"story":"该系列于2000年代初出现在德国的Liberty Cigar Company，后并入Villiger集团；它先离开洪都拉斯（Plasencia曾在那里卷制），再离开多米尼加共和国（ABAM曾在那里卷制），转至Estelí：一款新配方（茄衣为尼加拉瓜criollo，茄套来自多米尼加的Cibao，茄芯来自尼加拉瓜的Jalapa与Estelí）于2022年一月在Las Vegas的TPE展会上亮相，规格为Corona、Robusto和Gran Toro。2026年十月，公司页面将其列入手工制作雪茄之列，共四种规格（Gordito、Robusto、Corona、Gran Toro），在其等级表上为4级（共5级）。"},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut（厄瓜多尔）","vitolas":[],"story":"该系列于2025年以新配方重新推出，茄衣为厄瓜多尔Connecticut Shade，茄套来自尼加拉瓜，茄芯来自尼加拉瓜与多米尼加共和国，2025年四月在PCA展会上宣布，规格为Lonsdale（6 x 43）、Robusto（5 x 50）、Toro（6 x 50）和Churchill（7 x 50）；2026年七月的一篇报道称，此前的版本使用habano茄衣。Cigarworld.de称其在Estelí由Tabacalera Villiger de Nicaragua手工卷制，采用longfiller，在Joya de Nicaragua的场地内进行，并自2025年八月二十八日起将其收入目录；2026年十月，公司页面列出Robusto、Toro和Churchill，在其等级表上为2级（共5级）。"},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"未公开","vitolas":[],"story":"该系列于2017年五月在欧洲推出，有两个版本：洪都拉斯版（据一篇发布报道，由Nestor A. Plasencia在Danlí卷制）与多米尼加共和国版（据另一篇报道，在ABAM制作），规格为Robusto+（5 x 56）和Toro+（6 x 52）。2026年十月，公司页面将其列为四种产地：洪都拉斯、多米尼加共和国、尼加拉瓜和巴西，在其等级表上依次为4级、2.5级、5级和3.5级（共5级），并将其面向手工卷制雪茄的爱好者；Villiger将Corrida列入其位于Estelí的工厂所产品牌之列，该工厂于2021年九月底竣工。"},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"尼加拉瓜","vitolas":[],"story":"该系列据Cigarworld.de称在Dortmund举行的InterTabac 2023上发布；该零售商称其在Estelí与Joya de Nicaragua合作手工卷制，采用longfiller，茄衣与茄芯来自尼加拉瓜，茄套来自印尼，并自2023年九月二十五日起将5 x 52规格收入目录。2026年十月，公司页面列出三种以尺寸命名的规格：4 x 56、5 x 52和6 x 54，在其等级表上为4级（共5级）；2013年四月的一篇预览报道已经以此名称介绍了一个使用三种茄衣的系列。"}]',
  `gamme_ar` = '[{"name":"Villiger La Meridiana","color":"#2C1A0E","story":"التشكيلة الاستثنائية — تحيّة إلى المنطقة الناطقة بالإيطالية في سويسرا (تيتشينو). غلاف Oscuro إكوادوري على خلطة من نيكاراغوا والبرازيل. طابع أشدّ كثافة، بشوكولاتة داكنة وفلفل طويل. وهو الجواب السويسري عن سؤال ما يمكن للقارة أن تقدّمه في مواجهة كبار العالم الجديد."},{"name":"Villiger Cuellar Nicaragua","color":"#5C3317","story":"تعاون مع عائلة Cuellar في Estelí. غلاف Colorado طبيعي على خلطة نيكاراغوية خالصة. إنه الموقع السويسري داخل العالم الجديد — دقيق ومنتظم، أقلّ مغامرة من Padrón لكنه موثوق جداً."},{"name":"Havana Club","color":"#7A2E1E","force":"Medium","story":"اسمُ علامة كوبية قديمة، أعادت Villiger إطلاقه سنة 2007 سيجارًا دومينيكيًّا، يُلفّ في ABAM — مصنع Villiger في جمهورية الدومينيكان الذي تسمّيه هذه البطاقة هنا. وكان إحصاء هذا الأطلس يحسبه دارًا.","vitolas":[],"wrapper":"غير معلن"},{"name":"Dominico","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut Shade (إكوادور)","vitolas":[],"story":"خط من جمهورية الدومينيكان، تصفه صفحة الشركة في أكتوبر 2026 بأنه خفيف إلى متوسط وبسعر ميسور، عند المستوى 2 من 5 على سلّم Villiger، بخمسة مقاسات: Perla وCorona وRobusto وTorpedo وChurchill. ويذكر Cigarworld.de، وهو تاجر تجزئة ألماني، أنه ملفوف يدويًا من نوع longfiller لدى ABAM Cigars، ضمن bundles، بغلاف خارجي Connecticut Shade من إكوادور ورابط من إندونيسيا وحشوة Piloto من جمهورية الدومينيكان ومن نيكاراغوا؛ وتعود العلامة إلى مطلع سنوات 2000 بحسب هذا التاجر، الذي يُدرجها في فهرسه، بالنسبة إلى Corona، منذ 7 ديسمبر 2010."},{"name":"Casa de Nicaragua","color":"#8B5A2B","force":"Medium-Full","wrapper":"إكوادور (H-2000)","vitolas":[],"story":"قُدّمت في 2014 على يد Villiger بحسب Cigarworld.de، الذي يُدرجها في فهرسه منذ 12 أغسطس 2014 ويقول إنها ملفوفة يدويًا من نوع mediumfiller، بغلاف خارجي H-2000 من إكوادور ورابط من إندونيسيا وحشوة من نيكاراغوا. وتعدّها Villiger من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021؛ وفي أكتوبر 2026 تذكر صفحة الشركة خمسة مقاسات من أصل نيكاراغوا (Perla وCorona وRobusto وTorpedo وChurchill)، عند المستوى 4 من 5 على سلّمها."},{"name":"La Libertad","color":"#8B5A2B","force":"Medium-Full","wrapper":"Criollo (نيكاراغوا)","vitolas":[],"story":"ظهرت في مطلع سنوات 2000 لدى Liberty Cigar Company في ألمانيا، ثم انضمّت إلى مجموعة Villiger، وغادرت هندوراس، حيث كانت Plasencia تلفّها، ثم جمهورية الدومينيكان، حيث كانت ABAM تلفّها، إلى Estelí: مزيج جديد بغلاف خارجي criollo من نيكاراغوا ورابط من Cibao الدومينيكي وحشوة نيكاراغوية من Jalapa وEstelí عُرض في يناير 2022 في معرض TPE في Las Vegas بمقاسات Corona وRobusto وGran Toro. وفي أكتوبر 2026 تُدرجها صفحة الشركة ضمن سيجاراتها المصنوعة يدويًا، بأربعة مقاسات (Gordito وRobusto وCorona وGran Toro)، عند المستوى 4 من 5 على سلّمها."},{"name":"La Capitana","color":"#C9A96E","force":"Mild-Medium","wrapper":"Connecticut (إكوادور)","vitolas":[],"story":"أُعيد إطلاقها في 2025 بمزيج جديد، بغلاف خارجي Connecticut Shade من إكوادور ورابط من نيكاراغوا وحشوة من نيكاراغوا ومن جمهورية الدومينيكان، وأُعلن عنها في معرض PCA في أبريل 2025 بمقاسات Lonsdale (6 x 43) وRobusto (5 x 50) وToro (6 x 50) وChurchill (7 x 50)؛ وكانت النسخة السابقة بغلاف خارجي habano، بحسب تقرير في يوليو 2026. ويقول Cigarworld.de إنها ملفوفة يدويًا من نوع longfiller في Estelí لدى Tabacalera Villiger de Nicaragua، في مباني Joya de Nicaragua، ويُدرجها في فهرسه منذ 28 أغسطس 2025؛ وفي أكتوبر 2026 تذكر صفحة الشركة Robusto وToro وChurchill، عند المستوى 2 من 5 على سلّمها."},{"name":"Corrida","color":"#8B5A2B","force":null,"wrapper":"غير معلن","vitolas":[],"story":"أُطلقت في أوروبا في مايو 2017 بنسختين: هندوراس (ملفوفة في Danlí على يد Nestor A. Plasencia، بحسب تقرير عن الإطلاق) وجمهورية الدومينيكان (صُنعت لدى ABAM، بحسب تقرير آخر)، بمقاسي Robusto+ (5 x 56) وToro+ (6 x 52). وفي أكتوبر 2026 تعرضها صفحة الشركة بأربعة بلدان منشأ هي هندوراس وجمهورية الدومينيكان ونيكاراغوا والبرازيل، عند المستويات 4 و2,5 و5 و3,5 من 5 على سلّمها، وتوجّهها إلى هواة السيجار الملفوف يدويًا؛ وتعدّ Villiger علامة Corrida من علامات مصنعها في Estelí، الذي اكتمل في أواخر سبتمبر 2021."},{"name":"Nicaroma","color":"#8B5A2B","force":"Medium-Full","wrapper":"نيكاراغوا","vitolas":[],"story":"سلسلة قُدّمت في InterTabac 2023 في Dortmund بحسب Cigarworld.de، الذي يقول إنها ملفوفة يدويًا من نوع longfiller في Estelí بالشراكة مع Joya de Nicaragua، بغلاف خارجي وحشوة من نيكاراغوا ورابط من إندونيسيا، ويُدرجها في فهرسه منذ 25 سبتمبر 2023 للمقاس 5 x 52. وفي أكتوبر 2026 تذكر صفحة الشركة ثلاثة مقاسات مسمّاة بأبعادها: 4 x 56 و5 x 52 و6 x 54، عند المستوى 4 من 5 على سلّمها؛ وكان عرض تمهيدي في أبريل 2013 قد قدّم بالفعل تحت هذا الاسم خطًا بثلاثة أغلفة خارجية."}]',
  `source` = IF(LOCATE('villigercigars.com « Handmade Cigars » (7 octobre 2026 : sou', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'villigercigars.com « Handmade Cigars » (7 octobre 2026 : sous « Our brands », la maison range Nicaroma, La Capitana, Casa de Nicaragua, Corrida, Dominico et La Libertad parmi ses cigares premium faits à la main ; Corrida destinée aux amateurs de cigares roulés à la main) ; villigercigars.com « Product: DOMINICO » (7 octobre 2026 : République dominicaine, ligne légère à moyenne présentée comme abordable, niveau 2 sur 5, cinq formats Perla, Robusto, Corona, Torpedo, Churchill) ; villigercigars.com « Product: CASA DE NICARAGUA » (7 octobre 2026 : origine Nicaragua, niveau 4 sur 5, cinq formats Perla, Robusto, Corona, Torpedo, Churchill) ; villigercigars.com « Product: LA LIBERTAD » (7 octobre 2026 : origine Nicaragua, niveau 4 sur 5, quatre formats Gordito, Robusto, Corona, Gran Toro) ; villigercigars.com « Product: LA CAPITANA » (7 octobre 2026 : origine Nicaragua, niveau 2 sur 5, Robusto 5 x 50, Toro 6 x 50, Churchill 7 x 50) ; villigercigars.com « Product: CORRIDA » (7 octobre 2026 : versions Honduras, République dominicaine, Nicaragua et Brésil, niveaux 4, 2,5, 5 et 3,5 sur 5, Robusto+ et Toro+) ; villigercigars.com « Product: NICAROMA » (7 octobre 2026 : origine Nicaragua, niveau 4 sur 5, formats 4 x 56, 5 x 52 et 6 x 54, cigares roulés à la main) ; villigercigars.com « Blog: New VILLIGER cigar factory in Nicaragua » (usine d''Estelí achevée fin septembre 2021, cigares premium roulés à la main pour tous les marchés Villiger, environ seize marques dont La Libertad, Casa de Nicaragua et Corrida) ; cigarworld.de « Dominico Bundles Corona » (7 octobre 2026 : fabrication totalmente a mano, longfiller, tabacalera ABAM Cigars, cape Connecticut Shade d''Équateur, liant d''Indonésie, tripe Piloto de République dominicaine et du Nicaragua, importée par Villiger Söhne GmbH, au catalogue depuis le 7 décembre 2010) ; cigarworld.de « Dominico: Buy Cigars » (7 octobre 2026 : marque apparue au début des années 2000, cinq formats en bundles) ; cigarworld.de « Casa de Nicaragua Robusto » (7 octobre 2026 : présentée en 2014 par Villiger, au catalogue depuis le 12 août 2014, fabrication totalmente a mano, mediumfiller, cape H-2000 d''Équateur, liant d''Indonésie, tripe du Nicaragua) ; cigarworld.de « La Capitana Robusto » (7 octobre 2026 : fabrication totalmente a mano, longfiller, cape Connecticut d''Équateur, liant du Nicaragua, tripe de République dominicaine et du Nicaragua, tabacalera Villiger de Nicaragua dans les locaux de Joya de Nicaragua, au catalogue depuis le 28 août 2025) ; cigarworld.de « Nicaroma » (7 octobre 2026 : présentée à InterTabac 2023 à Dortmund, faite en partenariat avec Joya de Nicaragua et roulée à la main à Estelí) ; cigarworld.de « Nicaroma 5 x 52 » (7 octobre 2026 : totalmente a mano, longfiller, cape du Nicaragua, liant d''Indonésie, tripe du Nicaragua, au catalogue depuis le 25 septembre 2023) ; cigar-coop.com « Revamped Villiger La Capitana to Debut at PCA 2025 » (2 avril 2025 : version roulée à la main relancée, Villiger de Nicaragua à Estelí, cape Connecticut d''Équateur, liant du Nicaragua, tripe du Nicaragua et de République dominicaine, Lonsdale, Robusto, Toro et Churchill, annoncée au PCA du 12 avril 2025) ; cigar-coop.com « La Capitana Toro 2025 by Villiger Cigars » (9 juillet 2026 : version précédente à cape habano, mélange de 2025 à cape Connecticut Shade) ; cigar-coop.com « Cigar News: New Iteration of Villiger La Libertad Showcased at TPE 22 » (29 janvier 2022 : Villiger de Nicaragua à Estelí, cape criollo du Nicaragua, liant du Cibao, tripe de Jalapa et d''Estelí, Corona, Robusto, Gran Toro ; avant, Plasencia au Honduras puis ABAM en République dominicaine) ; cigarjournal.com « La Libertad moves from Honduras to Nicaragua » (9 août 2021 : marque apparue au début des années 2000 chez Liberty Cigar Company en Allemagne, distribuée par El Mundo del Tabaco, filiale de Villiger Söhne GmbH, puis intégrée au groupe Villiger) ; cigarjournal.com « Villiger Launches New Cigar Line Corrida in Europe » (3 mai 2017 : versions Honduras roulée chez Plasencia et République dominicaine faite à ABAM, Robusto+ 5 x 56 et Toro+ 6 x 52) ; cigarslover.com « Villiger presents Corrida line » (mai 2017 : version hondurienne produite à Danlí par Nestor A. Plasencia) ; cigarjournal.com « Villiger – New Discoveries » (16 septembre 2023 : Nicaroma, tabacs nicaraguayens sauf le liant d''Indonésie, usine neuve d''Estelí, formats 4 x 56, 5 x 52, 6 x 54) ; cigar-coop.com « Cigar Preview: Villiger NicaRoma » (4 avril 2013 : ligne à trois capes, Connecticut du Honduras, habano du Nicaragua, maduro de San Andrés)')),
  `updated_at` = NOW()
 WHERE `name` = 'Villiger';

-- ── Warped — paragraphe : Edition One ──
UPDATE `brands` SET
  `history` = IF(LOCATE('Edition One est le nom d''Edition One, Inc., société de Kyle ', `history`) > 0, `history`, CONCAT(`history`, '

', 'Edition One est le nom d''Edition One, Inc., société de Kyle Gellis, fondateur de Warped, et de son frère cadet Devin. Son seul cigare, Cloud Hopper, a été lancé en douceur en 2016 puis connu du public à l''été 2017, dit Cigar Wars. En octobre 2026, warpedcigars.com le présente parmi les marques de Warped, fait à TABSA avec Kyle Gellis pour blender, sans le nom d''Edition One ; Neptune Cigar le vend, fait à la main au Nicaragua, sous le nom Edition One Cloud Hopper, Cigars Direct sous le nom Warped Cloud Hopper.')),
  `history_en` = IF(LOCATE('Edition One is the name of Edition One, Inc., the company of', `history_en`) > 0, `history_en`, CONCAT(`history_en`, '

', 'Edition One is the name of Edition One, Inc., the company of Kyle Gellis, founder of Warped, and of his younger brother Devin. Its only cigar, Cloud Hopper, was quietly launched in 2016 and became known to the public in the summer of 2017, says Cigar Wars. In October 2026, warpedcigars.com presents it among the Warped brands, made at TABSA with Kyle Gellis as blender, without the name Edition One; Neptune Cigar sells it, handmade in Nicaragua, under the name Edition One Cloud Hopper, and Cigars Direct under the name Warped Cloud Hopper.')),
  `history_es` = IF(LOCATE('Edition One es el nombre de Edition One, Inc., empresa de Ky', `history_es`) > 0, `history_es`, CONCAT(`history_es`, '

', 'Edition One es el nombre de Edition One, Inc., empresa de Kyle Gellis, fundador de Warped, y de su hermano menor Devin. Su único puro, Cloud Hopper, se lanzó discretamente en 2016 y se dio a conocer al público en el verano de 2017, según Cigar Wars. En octubre de 2026, warpedcigars.com lo presenta entre las marcas de Warped, hecho en TABSA con Kyle Gellis como maestro mezclador, sin el nombre de Edition One; Neptune Cigar lo vende, hecho a mano en Nicaragua, con el nombre Edition One Cloud Hopper, y Cigars Direct con el nombre Warped Cloud Hopper.')),
  `history_de` = IF(LOCATE('Edition One ist der Name von Edition One, Inc., dem Unterneh', `history_de`) > 0, `history_de`, CONCAT(`history_de`, '

', 'Edition One ist der Name von Edition One, Inc., dem Unternehmen von Kyle Gellis, dem Gründer von Warped, und von dessen jüngerem Bruder Devin. Die einzige Zigarre von Edition One, Cloud Hopper, wurde 2016 leise eingeführt und im Sommer 2017 öffentlich bekannt, sagt Cigar Wars. Im Oktober 2026 stellt warpedcigars.com sie unter den Marken von Warped vor, bei TABSA gefertigt, mit Kyle Gellis als Mischmeister, ohne den Namen Edition One; Neptune Cigar verkauft sie, in Nicaragua von Hand gefertigt, unter dem Namen Edition One Cloud Hopper, Cigars Direct unter dem Namen Warped Cloud Hopper.')),
  `history_zh` = IF(LOCATE('Edition One是Edition One, Inc.的名称，该公司归Warped创始人Kyle Gellis及其弟', `history_zh`) > 0, `history_zh`, CONCAT(`history_zh`, '

', 'Edition One是Edition One, Inc.的名称，该公司归Warped创始人Kyle Gellis及其弟弟Devin所有。据Cigar Wars所述，其唯一的雪茄Cloud Hopper于2016年低调推出，2017年夏季为公众所知。2026年十月，warpedcigars.com将其列为Warped旗下品牌之一，由TABSA制造，Kyle Gellis担任调配师，但未出现Edition One这一名称；Neptune Cigar销售这款在尼加拉瓜手工制作的雪茄，名称为Edition One Cloud Hopper，Cigars Direct则以Warped Cloud Hopper之名销售。')),
  `history_ar` = IF(LOCATE('Edition One هو اسم Edition One, Inc.، وهي شركة تعود إلى Kyle', `history_ar`) > 0, `history_ar`, CONCAT(`history_ar`, '

', 'Edition One هو اسم Edition One, Inc.، وهي شركة تعود إلى Kyle Gellis، مؤسس Warped، وإلى شقيقه Devin الذي يصغره سنًا. وسيجارها الوحيد Cloud Hopper أُطلق بهدوء في 2016 ثم عُرف لدى الجمهور في صيف 2017، بحسب Cigar Wars. وفي أكتوبر 2026 يعرضه warpedcigars.com ضمن علامات Warped، مصنوعًا في TABSA، مع Kyle Gellis بصفته خبير المزج، من دون اسم Edition One؛ ويبيعه Neptune Cigar، مصنوعًا يدويًا في نيكاراغوا، باسم Edition One Cloud Hopper، ويبيعه Cigars Direct باسم Warped Cloud Hopper.')),
  `mentions` = '["Edition One"]',
  `source` = IF(LOCATE('cigarwars.net « Edition One, Inc. » (7 octobre 2026 : sociét', `source`) > 0, `source`, CONCAT(`source`, ' ; ', 'cigarwars.net « Edition One, Inc. » (7 octobre 2026 : société de Kyle Gellis, propriétaire de Warped Cigars, et de son frère cadet Devin ; Cloud Hopper, son seul cigare, lancé en douceur en 2016 puis connu du public à l''été 2017 ; fait à TABSA, au Nicaragua) ; warpedcigars.com « Warped Cigars | Boutique Cigar Company by Kyle Gellis » (7 octobre 2026 : Cloud Hopper figure parmi les marques de l''accueil, Edition One n''y figure pas) ; warpedcigars.com « Cloud Hopper | Warped Cigars » (7 octobre 2026 : No. 53 en 5 1/4 x 42 et No. 485 en 5 x 48, usine TABSA, blender Kyle Gellis ; le nom d''Edition One n''y figure pas) ; neptunecigar.com « Edition One Cloud Hopper No. 53 » (7 octobre 2026 : vendu sous ce nom, en stock ; fait à la main au Nicaragua par Tabacos Valle de Jalapa S.A. ; cigare attribué à Devin Gellis, avec son frère Kyle, fondateur de Warped Cigars) ; cigarsdirect.com « Warped Cloud Hopper Cigars | Buy Online at Discount Prices and Save – Cigars Direct » (7 octobre 2026 : vendu sous le nom Warped Cloud Hopper, formats No.53 et No.485) ; cigardojo.com « Edition One Cloud Hopper No. 53 Review » (10 novembre 2017 : Edition One, Inc. menée par les frères Kyle et Devin Gellis ; cigare sorti début 2016 selon l''article ; fait par Tabacos Valle de Jalapa S.A. à Estelí)')),
  `updated_at` = NOW()
 WHERE `name` = 'Warped';

-- ── Les sceaux des champs touchés, calculés depuis les colonnes ──
INSERT INTO `translation_status` (`entite`, `entite_id`, `champ`, `lang`, `source_hash`, `statut`, `maj`)
SELECT 'brands', b.`name`, c.champ, l.lang,
       SHA1(CASE c.champ WHEN 'history' THEN b.`history` ELSE b.`gamme` END), 'machine', NOW()
  FROM `brands` b
  JOIN (SELECT 'Villiger' hote, 'gamme' champ
        UNION ALL SELECT 'Warped' hote, 'history' champ) c
  JOIN (SELECT 'en' lang UNION ALL SELECT 'es' UNION ALL SELECT 'de' UNION ALL SELECT 'zh' UNION ALL SELECT 'ar') l
 WHERE c.hote = b.`name`
    ON DUPLICATE KEY UPDATE `source_hash` = VALUES(`source_hash`), `statut` = 'machine', `maj` = NOW();

